"""Ejecuta ProductionReset Java real con dobles de Android/SQLite y fallos controlados."""
from pathlib import Path
import subprocess,tempfile
ROOT=Path(__file__).resolve().parents[2]
fixtures={
'android/app/Activity.java':'''package android.app;public class Activity{public void runOnUiThread(Runnable r){r.run();}public void finishAffinity(){}}''',
'android/os/Process.java':'''package android.os;import java.util.concurrent.*;public class Process{public static CountDownLatch killed=new CountDownLatch(1);public static int myPid(){return 1;}public static void killProcess(int id){killed.countDown();}}''',
'android/widget/Toast.java':'''package android.widget;import android.app.Activity;public class Toast{public static final int LENGTH_LONG=1;public static Toast makeText(Activity a,String s,int n){return new Toast();}public void show(){}}''',
'android/content/ContentValues.java':'''package android.content;public class ContentValues extends java.util.HashMap<String,String>{}''',
'android/database/sqlite/SQLiteDatabase.java':'''package android.database.sqlite;import org.json.*;import android.content.*;
public class SQLiteDatabase{public JSONObject tables=new JSONObject();public JSONObject old;public boolean successful,failDelete;public int deletes;public void beginTransaction(){old=new JSONObject(tables.toString());successful=false;}public void setTransactionSuccessful(){successful=true;}public void endTransaction(){if(!successful)tables=old;}public int delete(String table,String where,String[] args){deletes++;if(failDelete){failDelete=false;throw new IllegalStateException("Fallo SQLite ficticio");}tables.put(table,new JSONArray());return 1;}public long insertOrThrow(String table,String hack,ContentValues values){tables.getJSONArray(table).put(new JSONObject(values));return 1;}}''',
'cu/hogarplaya/AppStore.java':'''package cu.hogarplaya;import org.json.*;import java.util.*;import android.app.*;import android.database.sqlite.*;
public class AppStore{public static AppStore current;public final String deviceId="old-device";public final Prefs prefs=new Prefs();public final SQLiteDatabase db=new SQLiteDatabase();public static AppStore get(Activity a){return current;}public SQLiteDatabase getWritableDatabase(){return db;}public String cache(String name,String fallback){JSONArray a=db.tables.getJSONArray("cache");for(int i=0;i<a.length();i++)if(name.equals(a.getJSONObject(i).optString("name")))return a.getJSONObject(i).getString("payload");return fallback;}
public static class Prefs{public final Map<String,String> values=new HashMap<>();public boolean failDone;public String getString(String k,String d){return values.getOrDefault(k,d);}public Editor edit(){return new Editor(this);}}
public static class Editor{Prefs p;Map<String,String> put=new HashMap<>();Set<String> remove=new HashSet<>();Editor(Prefs p){this.p=p;}public Editor putString(String k,String v){put.put(k,v);return this;}public Editor putBoolean(String k,boolean v){put.put(k,Boolean.toString(v));return this;}public Editor remove(String k){remove.add(k);return this;}public boolean commit(){if(p.failDone&&put.containsKey("productionReset173Done")){p.failDone=false;return false;}for(String k:remove)p.values.remove(k);p.values.putAll(put);return true;}}}''',
'cu/hogarplaya/Vault.java':'''package cu.hogarplaya;import android.app.Activity;public class Vault{public static String value="old-token";public Vault(Activity a){}public String token(){return value;}public void putToken(String s){value=s;}}''',
'cu/hogarplaya/SyncEngine.java':'''package cu.hogarplaya;import java.util.concurrent.*;import android.app.Activity;public class SyncEngine{public static boolean connected;public static final ExecutorService WORK=Executors.newSingleThreadExecutor();public static boolean online(Activity a){return connected;}}''',
'cu/hogarplaya/HouseholdFeatures.java':'''package cu.hogarplaya;import android.app.Activity;import org.json.*;public class HouseholdFeatures{static String actor(Activity a){return "ana";}static void reply(Activity a,String id,JSONObject data,Exception e){}}''',
'cu/hogarplaya/HouseholdDocuments.java':'''package cu.hogarplaya;import org.json.*;public class HouseholdDocuments extends android.app.Activity{public volatile String error;JSONObject productionSnapshot(){AppStore s=AppStore.current;return new JSONObject().put("format","hogar-finanzas-private-2").put("createdAt",java.time.Instant.now().toString()).put("tables",new JSONObject(s.db.tables.toString())).put("prefs",new JSONObject().put("endpoint",s.prefs.getString("endpoint","")).put("deviceId",s.deviceId)).put("token",Vault.value);}static JSONObject productionTables(AppStore s){return new JSONObject(s.db.tables.toString());}void productionError(String s){error=s;}}'''}
with tempfile.TemporaryDirectory(prefix='hogar-production-native-') as folder:
 p=Path(folder);files=[]
 for name,body in fixtures.items():
  f=p/name;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(body);files.append(f)
 files+=[ROOT/'1.6.0/native'/n for n in ['ProductionData.java','ProductionReset.java']]+[Path(__file__).with_name('ProductionResetTest.java')]
 subprocess.run(['java','-m','jdk.compiler/com.sun.tools.javac.Main','-cp','/workspace/.tools/json.jar','-d',str(p),*map(str,files)],check=True)
 subprocess.run(['java','-cp',str(p)+':/workspace/.tools/json.jar','cu.hogarplaya.ProductionResetTest'],check=True,timeout=40)
